/**
 * SOUND — narration, optional music (auto-ducked) and sound effects.
 * Sound effects are generated by scripts/generate-sfx.mjs (no downloads).
 */
import React, {createContext, useContext} from 'react';
import {Audio, Sequence, staticFile, useVideoConfig} from 'remotion';
import {clamp} from '../lib/anim';

export type SfxName =
  | 'room-tone'
  | 'city-night'
  | 'typing'
  | 'notification'
  | 'send'
  | 'airport'
  | 'suitcase-roll'
  | 'rewind'
  | 'impact'
  | 'hit'
  | 'whoosh'
  | 'riser'
  | 'door-open'
  | 'door-close'
  | 'atmosphere'
  | 'ending'
  | 'office'
  | 'dawn'
  | 'page-flip'
  | 'shimmer'
  | 'phone-buzz';

export const SfxLevel = createContext(1);

/** One sound effect starting at `at` (scene-relative frame). */
export const Sfx: React.FC<{
  name: SfxName;
  at: number;
  volume?: number;
  duration?: number;
  fadeIn?: number;
  fadeOut?: number;
  loop?: boolean;
  rate?: number;
}> = ({name, at, volume = 1, duration, fadeIn = 0, fadeOut = 0, loop = false, rate = 1}) => {
  const level = useContext(SfxLevel);
  const {durationInFrames} = useVideoConfig();
  const len = duration ?? Math.max(1, durationInFrames - Math.max(0, at));
  return (
    <Sequence from={Math.round(at)} durationInFrames={Math.max(1, Math.round(len))} layout="none">
      <Audio
        src={staticFile(`audio/sound-effects/${name}.wav`)}
        loop={loop}
        playbackRate={rate}
        volume={(f) => {
          const fi = fadeIn > 0 ? clamp(f / fadeIn) : 1;
          const fo = fadeOut > 0 && duration ? clamp((len - f) / fadeOut) : 1;
          return volume * level * fi * fo;
        }}
      />
    </Sequence>
  );
};

/** Looping ambience bed for a whole scene, with fades. */
export const Ambience: React.FC<{name: SfxName; duration: number; volume?: number; fade?: number; at?: number}> = ({
  name,
  duration,
  volume = 0.5,
  fade = 20,
  at = 0,
}) => <Sfx name={name} at={at} duration={duration - at} volume={volume} fadeIn={fade} fadeOut={fade} loop />;
